def next_smallest_palindrome(num: int) -> int:
    """
    Find the next smallest palindrome strictly greater than the given number.
    Assumes num is zero or positive, and can be very large.

    Args:
    num (int): The input number.

    Returns:
    int: The next smallest palindrome greater than num.
    """
    # Convert number to string for easy manipulation
    s = str(num)

    # If num is less than 9, the next palindrome is num+1
    if num < 9:
        return num + 1

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all digits are 9, the next palindrome is 10..01 (length+1)
    if is_all_nines(s):
        return int('1' + ('0' * (len(s)-1)) + '1')

    length = len(s)
    mid = length // 2
    left = s[:mid]
    middle = s[mid] if length % 2 else ''
    right = s[mid+1:] if length % 2 else s[mid:]

    # Create a palindrome by reflecting the left + middle
    if length % 2 == 0:
        palindrome = left + left[::-1]
    else:
        palindrome = left + middle + left[::-1]

    if int(palindrome) > num:
        return int(palindrome)

    # Increment the middle part and propagate the carry if necessary
    if length % 2 == 0:
        # Even length
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)
        # If incrementing left changes its length, adjust palindrome accordingly
        if len(left_str) > len(left):
            # This happens if left was like 99..9, so palindrome becomes 100..001
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = left_str + left_str[::-1]
    else:
        # Odd length
        left_middle = left + middle
        left_middle_num = int(left_middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)
        if len(left_middle_str) > len(left_middle):
            # e.g. 999 -> 1000
            # palindrome becomes 100...001
            return int('1' + ('0' * (length -1)) + '1')
        palindrome = left_middle_str + left_middle_str[:-1][::-1]

    return int(palindrome)

