def get_noOfways(n: int) -> int:
    # Handle base cases
    if n == 0:
        return 1  # Assuming 1 way to stay at the start (no steps)
    if n == 1:
        return 1  # Only 1 way to reach step 1

    # dp[i] will store the number of ways to reach step i
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1

    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]

    return dp[n]

