def find_solution(a, b, n):
    """
    Find the first non-negative integer solution (x, y) to the equation:
        a*x + b*y = n

    Starting from x = 0 and increasing x until a valid y is found.
    Returns a tuple (x, y) if solution exists, otherwise None.
    """
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)

    x = 0
    while True:
        remainder = n - a * x
        # We want y to be integer and non-negative
        if b != 0 and remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        elif b == 0:
            # If b=0, equation is a*x = n, check if x is solution
            if remainder == 0:
                return (x, 0)
        x += 1
        # To avoid infinite loop if no solution:
        # If a and b are positive, once a*x > n, no solutions with x>=0
        # If a or b are negative, we can't be sure, so no bound imposed.
        if a > 0 and x > n:
            break
    return None

