from collections.abc import Iterable

def remove_column(data, pos):
    """
    Recursively remove the element at index `pos` from each inner grouping within `data`.

    Args:
        data: A multi-level collection (e.g., nested lists/tuples) of arbitrary depth.
        pos: The index position to remove from each inner grouping.

    Returns:
        A new data structure with the same shape as `data` but with the element at `pos` removed from every inner grouping.
        Non-grouping elements remain unchanged.
    """
    # Helper to check if an object is a grouping (list or tuple)
    def is_grouping(x):
        # str should not be considered iterable here
        return isinstance(x, (list, tuple))

    if not is_grouping(data):
        # Base case: not a grouping, return as is
        return data

    # If this is an inner grouping of non-groupings, remove the element at pos if possible
    # But we need to distinguish deeper nesting vs inner grouping of elements

    # Check if elements inside are groupings or not
    # If elements are all non-groupings (or empty), remove pos element here
    # Otherwise, recurse into each element

    # If empty grouping, just return empty of the same type
    if len(data) == 0:
        return type(data)()

    # Check if the elements inside are groupings
    if all(not is_grouping(el) for el in data):
        # Inner grouping - remove element at pos if possible
        if 0 <= pos < len(data):
            new_data = data[:pos] + data[pos+1:]
        else:
            # pos out of range, return original
            new_data = data[:]
        # Return same type
        return type(data)(new_data)
    else:
        # Elements are themselves groupings - recurse into each element
        return type(data)(remove_column(el, pos) for el in data)

