def count_list(collection, structure):
    """
    Count occurrences of `structure` inside `collection`.
    Overlapping occurrences are counted separately.

    Args:
        collection (list): A list which may contain nested structures.
        structure (list): The structure to count occurrences of.

    Returns:
        int: The total count of occurrences of `structure` in `collection`.
    """
    def is_sublist_at(lst, sublst, start):
        """Check if sublst occurs in lst starting at index start."""
        if start + len(sublst) > len(lst):
            return False
        return lst[start:start + len(sublst)] == sublst

    def count_in_list(lst, sublst):
        count = 0
        i = 0
        while i <= len(lst) - len(sublst):
            if is_sublist_at(lst, sublst, i):
                count += 1
                i += 1  # Allow overlapping by advancing only one step
            else:
                i += 1
        # Also recursively count inside nested lists
        for item in lst:
            if isinstance(item, list):
                count += count_in_list(item, sublst)
        return count

    return count_in_list(collection, structure)

