def compute_Last_Digit(A: int, B: int) -> int:
    # If A == B, the product is empty, so return 1 (neutral element)
    if A == B:
        return 1

    # If B - A >= 5, product includes at least one multiple of 10,
    # so last digit is 0
    if B - A >= 5:
        return 0

    product = 1
    for num in range(A + 1, B + 1):
        product *= num
    return product % 10

