    """
    Check if 'subset' is a subset of 'superset'.

    Both inputs should be iterable. Elements should be hashable.

    Returns True if every element in 'subset' is in 'superset', else False.

    Raises:
        TypeError: if inputs are not iterable or elements are unhashable.
    """
    try:
        superset_set = set(superset)
    except TypeError as e:
        raise TypeError(f"Superset argument is not iterable or contains unhashable elements: {e}")

    try:
        for elem in subset:
            if elem not in superset_set:
                return False
    except TypeError as e:
        raise TypeError(f"Subset argument is not iterable or contains unhashable elements: {e}")

    return True

