def next_smallest_palindrome(num: int) -> int:
    if num < 0:
        raise ValueError("Input number must be zero or positive")
    if num < 8:
        # For single digit numbers less than 8, just return num+1
        return num + 1

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    def next_palindrome(n: int) -> int:
        s = str(n)
        length = len(s)
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            palindrome = int(left + left[::-1])
        else:
            palindrome = int(left + left[-2::-1])

        if palindrome > n:
            return palindrome

        # Increment the left half and form palindrome again
        left_num = int(left) + 1
        left_str = str(left_num)
        if len(left_str) > len(left):
            # e.g. 999 + 1 = 1000 (length increased)
            return int('1' + ('0' * (length - 1)) + '1')

        if length % 2 == 0:
            palindrome = int(left_str + left_str[::-1])
        else:
            palindrome = int(left_str + left_str[-2::-1])
        return palindrome

    candidate = num + 1
    while True:
        if is_palindrome(candidate):
            return candidate
        candidate = next_palindrome(candidate)

