    low, high = 0, len(arr) - 1

    # If the array is not rotated (sorted in ascending order)
    if arr[low] < arr[high]:
        return arr[high]

    while low <= high:
        mid = (low + high) // 2

        # Check if mid element is maximum
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to choose for the max element
        if arr[mid] >= arr[low]:
            low = mid + 1
        else:
            high = mid - 1

    return -1  # Should never reach here if input is valid

