def substract_elements(nested):
    """
    Compute the differences of the values in the given nested collections.

    The function assumes the nested collections primarily contain numeric values.
    Non-numeric or empty elements are ignored in difference calculations.

    Args:
        nested: A nested collection (list, tuple, etc.) containing numeric values.

    Returns:
        A nested collection of the same structure where each numeric element is replaced
        by the difference with the previous numeric element in a flattened traversal.
        The first numeric element remains as is.
    """
    # Flatten numeric values while keeping track of positions
    positions = []
    values = []

    def flatten(collection):
        for idx, item in enumerate(collection):
            if isinstance(item, (list, tuple)):
                flatten(item)
            else:
                # Consider only numeric values
                if isinstance(item, (int, float)):
                    positions.append(idx)
                    values.append(item)

    flatten(nested)

    # Compute differences on values
    diffs = []
    prev = None
    for v in values:
        if prev is None:
            diffs.append(v)
        else:
            diffs.append(v - prev)
        prev = v

    # Rebuild nested structure with differences inplace of numeric values
    def rebuild(collection):
        result = []
        diff_iter = iter(diffs)

        for item in collection:
            if isinstance(item, (list, tuple)):
                rebuilt = rebuild(item)
                # Preserve original type
                if isinstance(item, tuple):
                    rebuilt = tuple(rebuilt)
                result.append(rebuilt)
            else:
                if isinstance(item, (int, float)):
                    result.append(next(diff_iter))
                else:
                    result.append(item)
        return result

    rebuilt = rebuild(nested)
    # Preserve top-level collection type
    if isinstance(nested, tuple):
        rebuilt = tuple(rebuilt)
    return rebuilt

