import re

def capital_words_spaces(s: str) -> str:
    # Insert space before a capital letter only if it is preceded by a lowercase letter or digit
    # This avoids splitting acronyms (consecutive capitals)
    return re.sub(r'(?<=[a-z0-9])([A-Z])', r' \1', s)

def lcm(a: int, b: int) -> int:
    def gcd(x: int, y: int) -> int:
        while y:
            x, y = y, x % y
        return x

    return a * b // gcd(a, b)

def substract_elements(t1, t2):
    """
    Subtract elements of the second nested tuple from the first nested tuple element-wise.
    Assumes both tuples have the same structure and dimensions.
    """
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        return tuple(substract_elements(a, b) for a, b in zip(t1, t2))
    else:
        return t1 - t2
